       v.rotation_name, v.weeks, v.leave_weeks, v.leave_position
from v join r on r.username = v.username cross join guard
on conflict (resident_id, academic_year, block_number, segment) do update set
  rotation_name  = excluded.rotation_name,
  weeks          = excluded.weeks,
  leave_weeks    = excluded.leave_weeks,
  leave_position = excluded.leave_position;

